xpath.script:
document.addEventListener( 'DOMContentLoaded', function() {
    var list = document.getElementsByClassName("splide-team");
    for (let item of list) {
        new Splide(
            item,
            {
                type: 'loop',
                autoplay: true,
                interval: 3000,
                perPage: 4,
                perMove: 1,
                easing: 'cubic-bezier(0.25, 0.1, 0.25, 1)',
                arrows: true,
                gap: '32px',
                breakpoints: {
                    1200: {
                        perPage: 3,
                    },
                    800: {
                        perPage: 2,
                    },
                    600: {
                        perPage: 1,
                    }
                }
            }
        ).mount();
    }

    var listNews = document.getElementsByClassName("splide-news");
    for (let newsItem of listNews) {
        new Splide(
            newsItem,
            {
                type: 'loop',
                autoplay: true,
                interval: 3000,
                perPage: 3,
                perMove: 1,
                easing: 'cubic-bezier(0.25, 0.1, 0.25, 1)',
                arrows: true,
                gap: '32px',
                breakpoints: {
                    1200: {
                        perPage: 3,
                    },
                    800: {
                        perPage: 2,
                    },
                    600: {
                        perPage: 1,
                    }
                }
            }
        ).mount();
    }
});
